// Sends Squid access-log lines to VictoriaLogs, already parsed the way our log pipeline parses them.
//   node push-logs.mjs injection   one VM read a poisoned Jira comment and keeps trying to send data out
//   node push-logs.mjs quiet       three normal runs, each with a few harmless denials
const VL = process.env.VL_URL ?? 'http://localhost:9428';
const line = (ip, host, code) => ({
  _time: new Date().toISOString(), _msg: `TCP_${code}/403 CONNECT ${host}:443`,
  'log.processing.type': 'squid_access', 'cloud.account.name': 'ai-agents',
  'source.address': ip, 'squid.result_code': code, 'url.domain': host,
});
const denied = (ip, hosts) => hosts.map((h) => line(ip, h, 'DENIED'));
const SCENES = {
  injection: [
    ...denied('10.20.3.14', ['paste.example.com', 'paste.example.com', 'transfer.example.net', 'github.com',
      'gist.github.com', 'paste.example.com', 'raw.example.org']),
    line('10.20.3.14', 'nexus.rhinohealth.com', 'ALLOWED'),
    ...denied('10.20.3.27', ['registry.npmjs.org', 'telemetry.example.io', 'github.com']),
  ],
  quiet: [
    ...denied('10.20.3.27', ['registry.npmjs.org', 'telemetry.example.io', 'github.com']),
    ...denied('10.20.3.31', ['github.com', 'registry.npmjs.org']),
    ...denied('10.20.3.40', ['telemetry.example.io', 'github.com', 'registry.npmjs.org']),
  ],
};
const scene = process.argv[2] ?? 'injection';
const lines = SCENES[scene];
const res = await fetch(`${VL}/insert/jsonline?_stream_fields=source.address`, { method: 'POST', body: lines.map((l) => JSON.stringify(l)).join('\n') });
console.log(`${scene}: sent ${lines.length} Squid log lines (${res.status})`);
EOF
