// A pretend #ai-agents-alerts: it plays Alertmanager and prints every alert vmalert sends to it.
import { createServer } from 'node:http';

createServer((req, res) => {
  let body = '';
  req.on('data', (c) => (body += c));
  req.on('end', () => {
    for (const a of JSON.parse(body || '[]')) {
      console.log(`#ai-agents-alerts  [${a.labels.severity}] ${a.annotations.summary}`);
      console.log(a.annotations.description.split('\n').map((l) => `    ${l}`).join('\n'));
    }
    res.end('{}');
  });
}).listen(process.env.ALERTS_PORT ?? 9093, () => console.log('pretend #ai-agents-alerts is listening'));
EOF

