// Builds the "Refused actions" section of one run's PR from three sources.   node refusals.mjs 0192f3a1
import { readFileSync } from 'node:fs';

const runId = process.argv[2] ?? '0192f3a1';
const VL = process.env.VL_URL ?? 'http://localhost:9428';
const jsonl = (file) => readFileSync(file, 'utf8').trim().split('\n').map((l) => JSON.parse(l));

// 1. The run's VM: the instance whose ai-agents:run-id tag is this run (aws ec2 describe-instances in the platform).
const vm = JSON.parse(readFileSync('instances.json', 'utf8'))
  .find((i) => i.Tags.some((t) => t.Key === 'ai-agents:run-id' && t.Value === runId));

// 2. The proxy's denials from that VM's IP, straight from VictoriaLogs.
const query = `_time:1d source.address:="${vm.PrivateIpAddress}" squid.result_code:="DENIED"`;
const res = await fetch(`${VL}/select/logsql/query?${new URLSearchParams({ query })}`);
const squid = (await res.text()).trim().split('\n').filter(Boolean).map((l) => JSON.parse(l));

// 3. Merge with the harness's ledger and the broker's audit, and count repeats.
const rows = [
  ...jsonl('ledger.jsonl').filter((r) => r.run === runId).map((r) => [`${r.tool} ${r.target}`, 'harness hook', r.reason]),
  ...jsonl('broker-audit.jsonl').filter((r) => r.run === runId).map((r) => [`${r.action} ${r.target}`, 'broker', r.reason]),
  ...squid.map((l) => [`web request to ${l['url.domain']}`, 'egress proxy', 'not on the allow-list']),
];
const counted = new Map();
for (const row of rows) counted.set(row.join('|'), (counted.get(row.join('|')) ?? 0) + 1);

if (counted.size === 0) process.exit(0); // nothing refused: no section in the PR
console.log('### Refused actions\n\n| What Nova tried | Refused by | Why |\n|---|---|---|');
for (const [key, n] of counted) {
  const [what, by, why] = key.split('|');
  console.log(`| ${what}${n > 1 ? ` (${n} times)` : ''} | ${by} | ${why} |`);
}
